IF TYPE_ID(N'[core].[Counter]') IS NULL
CREATE TYPE [core].[Counter] FROM int NOT NULL
GO
IF OBJECT_ID(N'[it''s].[by ]] alias]', N'SO') IS NULL
CREATE SEQUENCE [it's].[by ]] alias] AS [core].[Counter] START WITH 1000 INCREMENT BY 1 MINVALUE 1000 MAXVALUE 2147483647 NO CYCLE CACHE 50
GO
IF OBJECT_ID(N'[sales].[InvoiceNo]', N'SO') IS NULL
CREATE SEQUENCE [sales].[InvoiceNo] AS bigint START WITH 1000 INCREMENT BY 1 MINVALUE 1000 MAXVALUE 9223372036854775807 NO CYCLE CACHE 50
GO
IF OBJECT_ID(N'[sales].[cycling down]', N'SO') IS NULL
